func (s *Sandbox) Delete(ctx context.Context, options *DeleteOptions) error {
	timeout := effectiveTimeout(options.GetTimeout(), s.inheritedTimeout())
	operationContext, cancel, err := s.operationContext(ctx, "delete", timeout)
	if err != nil {
		return err
	}
	defer cancel()
	capability, ok := s.operations.(SandboxDeleter)
	if !ok {
		return s.unsupported("delete")
	}
	info, err := capability.DeleteSandbox(operationContext, s.ID(), providerOptions(options, timeout, func() *DeleteOptions { return &DeleteOptions{} }, func(cloned *DeleteOptions) {
		cloned.Timeout = Duration(*timeout)
	}))
	if err != nil {
		return WithErrorContext(err, s.ProviderName(), "delete")
	}
	if err := s.replaceInfo("delete", info); err != nil {
		return err
	}
	// Mark the handle terminal before cancel releases the operation gate.
	s.markTerminal(SandboxStateDeleted, "deleted")
	return nil
}

func TestCloseWaitsForTheCurrentOperation(t *testing.T) {
	entered := make(chan struct{})
	release := make(chan struct{})
	var calls int
	backend := &lifecycleBackend{start: func(_ context.Context, id string, _ *sandbox.StartOptions) (*sandbox.SandboxInfo, error) {
		calls++
		if calls == 1 {
			close(entered)
			<-release
		}
		return &sandbox.SandboxInfo{Id: id}, nil
	}}
	client, err := sandbox.NewClient(&lifecycleProvider{backend: backend}, &sandbox.Config{})
	if err != nil {
		t.Fatal(err)
	}
	instance, err := client.Create(context.Background(), nil)
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() { done <- instance.Start(context.Background(), nil) }()
	<-entered
	closed := make(chan error, 1)
	go func() { closed <- instance.Close(context.Background()) }()
	select {
	case err := <-closed:
		t.Fatalf("close returned while start still held the handle: %v", err)
	case <-time.After(50 * time.Millisecond):
	}
	close(release)
	if err := <-done; err != nil {
		t.Fatal(err)
	}
	if err := <-closed; err != nil {
		t.Fatal(err)
	}
	err = instance.Start(context.Background(), nil)
	var detail *sandbox.Error
	if !errors.As(err, &detail) || detail.Kind != sandbox.ErrorKindFailedPrecondition || calls != 1 {
		t.Fatalf("operation ran after close: %v calls=%d", err, calls)
	}
}

