            if not f.endswith('.go'):
                continue
            path = os.path.join(dirpath, f)
            if any(p in path for p in skip):
                continue
            lines = open(path).read().splitlines()
            for i, line in enumerate(lines):
                if not decl.match(line):
                    continue
                name_m = re.search(r'\b([A-Z]\w*)', line)
                if not name_m and not line.startswith('const (') and not line.startswith('var ('):
                    continue
                # unexported receiver methods that are exported still show if type is exported
                if line.startswith('func (') and '*backend' in line or 'backend)' in line:
                    continue
                j = i - 1
                while j >= 0 and lines[j].strip() == '':
                    j -= 1
                comments = []
                while j >= 0 and lines[j].lstrip().startswith('//'):
                    comments.append(lines[j].lstrip()[2:].strip())
                    j -= 1
                comments.reverse()
                first = comments[0] if comments else "MISSING"
                ident = name_m.group(1) if name_m else line
                # flag short or internal
                blob = " ".join(comments).lower()
                flags = []
                if not comments:
                    flags.append("NONE")
                elif len(comments) == 1 and len(comments[0]) < 80:
                    flags.append("SHORT")
                if any(w in blob for w in ("handwritten", "protobuf", "protovalidate", "specs/", "yaml", "unexported", "native sdk", "generated")):
                    flags.append("INTERNAL")
                if flags:
